// State 3 can return success yet render solid black on current Windows builds.
// Use the compatible accent-blur path with a minimal neutral tint instead of the
// standard system Acrylic recipe. Colored glass and reflections belong to WPF.
public int SetAeroGlass(IntPtr hwnd, bool dark) =>
    SetAccent(hwnd, 4, dark ? 0x08000000u : 0x08FFFFFFu);
        State = state, // 4: compatible accent blur, 0: disabled

// Missing/offscreen geometry also waits for a new frame or move notification,
// not an unproductive render loop while there is nothing to present.
if (_pendingFrame == null && _renderingSubscribed)

    Check("Aero uses its low-tint accent recipe and clears it across transitions", () =>
        Assert(f.Backdrop.IsActive && f.Api.Aero && f.Api.AccentState == 4 && f.Api.Backdrop == 1 &&
        Assert(f.Api.Aero && f.Api.AccentState == 4, "Clear Acrylic -> Aero replaces its accent recipe");
internal bool Aero;
    Assert(Backdrop == 1 && !Alpha && !Glass, "Aero accent blur is exclusive of system Acrylic and legacy alpha");
    ClearAcrylic = true; Aero = true; AccentState = 4; return 0;
    ClearAcrylic = enabled; Aero = false; AccentState = enabled ? 4 : 0; return 0;

var response = Math.Abs(wp.R-bp.R) + Math.Abs(wp.G-bp.G) + Math.Abs(wp.B-bp.B);
if (response <= 50)
{
    // Hosted Server can suppress all blur transparency. Only skip if
    // the independent, documented system Acrylic control also does.
    controller.State.PaperSkin = PaperSkins.Acrylic; Theme.Invalidate(); window.UpdateTheme();
    rear.Background = Brushes.White; Wait(150);
    using var systemWhite = NativeSurfaceChecks.Capture(window, output, $"study-system-{mode}-white-control");
    rear.Background = Brushes.RoyalBlue; Wait(150);
    using var systemBlue = NativeSurfaceChecks.Capture(window, output, $"study-system-{mode}-blue-control");
    var sw = systemWhite.GetPixel(340, 260); var sb = systemBlue.GetPixel(340, 260);
    Program.Assert(Math.Abs(sw.R-sb.R) + Math.Abs(sw.G-sb.G) + Math.Abs(sw.B-sb.B) <= 10,
        "Aero transparency failed while the documented system blur control responds normally");
    Console.WriteLine($"SKIP Aero rear-color comparison: system control also suppresses transparency ({sw}/{sb}); native Windows 11 appearance still requires manual acceptance.");
    controller.State.PaperSkin = PaperSkins.Aero; Theme.Invalidate(); window.UpdateTheme();
}
